  "a_sentences": [
    {
      "a_text": "Der Ausstand nach Art. 47 ZPO bezieht sich auf einzelne Gerichtspersonen und nicht auf einen Spruchkörper oder eine ganze Institution (P1).",
      "b_propositions": ["P1"]
    },
    {
      "a_text": "Die Ausstandsgründe sind daher substanziiert und in Bezug auf konkrete Personen vorzubringen (P2).",
      "b_propositions": ["P2"]
    },
    {
      "a_text": "Ihnen gegenüber sind die den Ausstand begründenden Tatsachen glaubhaft zu machen (Art. 49 Abs. 1 ZPO) (P3).",
      "b_propositions": ["P3"]
    },
    {
      "a_text": "Selbst wenn sämtliche Mitglieder eines Gerichts befangen sein sollten, sind die Ausstandsgründe substanziiert und in Bezug auf jede einzelne abgelehnte Person vorzubringen (P4).",
      "b_propositions": ["P4"]
    },
    {
      "a_text": "Dies gilt auch, wenn das Ausstandsgesuch offensichtlich unzulässig ist, weil es pauschal gegen ein ganzes Gericht oder gegen sämtliche Mitglieder gerichtet ist (P5).",
      "b_propositions": ["P5"]
    },
    {
      "a_text": "Die Argumentation der versicherten Person geht fehl (P6).",
      "b_propositions": ["P6"]
    },
    {
      "a_text": "Die Vorinstanz beurteilte das Ausstandsgesuch der versicherten Person zu Recht als unzulässig (P7).",
      "b_propositions": ["P7"]
    },
    {
      "a_text": "Nach dem Gesagten ist nicht zu beanstanden, dass die Vorinstanz auf das unzulässige Ausstandsgesuch ohne Einholung einer Stellungnahme und unter Mitwirkung der abgelehnten Gerichtspersonen nicht eintrat (P8).",
      "b_propositions": ["P8"]
    }
  ]
}
